-- Guarded private introductory research for exact Triumph and KTM IDs.
-- 11 models x two source-linked sections. No publication, ID or stock changes.
-- All text remains pending independent editorial/source review.
DO $$
DECLARE matched integer; inserted integer; public_before integer; public_after integer;
BEGIN
 SELECT count(*) INTO public_before FROM public.motorcycle_universal_published_sections_v1;
 WITH expected(id,make,model) AS (VALUES (663,'Triumph','Bonneville T120'),
(662,'Triumph','Bonneville T100'),
(661,'Triumph','Bonneville Bobber'),
(670,'Triumph','Speed Triple 1200 RS'),
(245,'Triumph','SPEED TRIPLE 1050'),
(1029,'Triumph','Street Triple 675'),
(524,'KTM','390 Duke'),
(205,'KTM','1290 Super Duke R'),
(523,'KTM','390 Adventure'),
(529,'KTM','890 Duke R'),
(527,'KTM','790 Duke'))
 SELECT count(*) INTO matched FROM expected e
 JOIN public.motorcycle_catalog_models m
 ON m.id=e.id AND m.manufacturer=e.make AND m.model=e.model
 WHERE NOT EXISTS(SELECT 1 FROM public.motorcycle_universal_page_sections_v1 s
 WHERE s.entity_type='model' AND s.model_id=e.id)
 AND NOT EXISTS(SELECT 1 FROM public.motorcycle_catalog_model_aliases a
 WHERE a.alias_model_id=e.id AND a.review_status<>'approved');
 IF matched<>11 THEN RAISE EXCEPTION 'Triumph/KTM intake stopped: expected 11 clean IDs; found %',matched; END IF;
 INSERT INTO public.motorcycle_universal_page_sections_v1
 (entity_type,manufacturer_id,model_id,section_number,section_title,content,editorial_status,source_reference,published_at)
 SELECT 'model',NULL,v.model_id,v.section_number,v.title,v.content,'draft',
 'manufacturer_archive_draft:'||v.url,NULL
 FROM (VALUES (663,1,'Model introduction','{"summary":"Triumph''s Bonneville T120 combines the marque''s classic twin-cylinder identity with the modern Bonneville range.","source_name":"Triumph manufacturer archive","source_url":"https://www.triumphmotorcycles.co.uk/our-story/bonneville","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://www.triumphmotorcycles.co.uk/our-story/bonneville'),
(663,7,'Documented model history','{"summary":"Triumph traces the T120 name to 1958 and records its return in 2016 with the redesigned 1,200 cc parallel-twin generation.","source_name":"Triumph manufacturer archive","source_url":"https://www.triumphmotorcycles.co.uk/our-story/bonneville","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://www.triumphmotorcycles.co.uk/our-story/bonneville'),
(662,1,'Model introduction','{"summary":"The Bonneville T100 is Triumph''s smaller-capacity modern-classic roadster within the Bonneville family.","source_name":"Triumph manufacturer archive","source_url":"https://www.triumphmotorcycles.co.uk/our-story/bonneville","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://www.triumphmotorcycles.co.uk/our-story/bonneville'),
(662,7,'Documented model history','{"summary":"Triumph''s official family history records the T100 launch in 2002, originally with a 790 cc twin, followed by later 865 cc and 900 cc generations.","source_name":"Triumph manufacturer archive","source_url":"https://www.triumphmotorcycles.co.uk/our-story/bonneville","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://www.triumphmotorcycles.co.uk/our-story/bonneville'),
(661,1,'Model introduction','{"summary":"The Bonneville Bobber applies Triumph''s modern-classic engineering to a stripped-back custom-inspired motorcycle.","source_name":"Triumph manufacturer archive","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/brand","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/brand'),
(661,7,'Documented model history','{"summary":"Triumph''s corporate timeline records the Bobber launch in 2016; later model-year equipment must be checked separately.","source_name":"Triumph manufacturer archive","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/brand","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/brand'),
(670,1,'Model introduction','{"summary":"The Speed Triple 1200 RS continues Triumph''s road-focused, high-performance naked-motorcycle line.","source_name":"Triumph manufacturer archive","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/events/speed-triple-30-year-celebration-2024-11-18","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/events/speed-triple-30-year-celebration-2024-11-18'),
(670,7,'Documented model history','{"summary":"Triumph''s 2024 retrospective records the Speed Triple 1200 RS arrival in 2021 and distinguishes it from the earlier Speed Triple 1050.","source_name":"Triumph manufacturer archive","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/events/speed-triple-30-year-celebration-2024-11-18","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/events/speed-triple-30-year-celebration-2024-11-18'),
(245,1,'Model introduction','{"summary":"The Speed Triple 1050 represented a major evolution of Triumph''s naked triple-cylinder roadster.","source_name":"Triumph manufacturer archive","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/events/speed-triple-30-year-celebration-2024-11-18","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/events/speed-triple-30-year-celebration-2024-11-18'),
(245,7,'Documented model history','{"summary":"Triumph''s retrospective specifically identifies the Speed Triple 1050 as a 2005 milestone; later versions require generation-specific documentation.","source_name":"Triumph manufacturer archive","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/events/speed-triple-30-year-celebration-2024-11-18","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/events/speed-triple-30-year-celebration-2024-11-18'),
(1029,1,'Model introduction','{"summary":"Triumph''s Street Triple 675 combined naked roadster styling with engineering derived from the Daytona 675 generation.","source_name":"Triumph manufacturer archive","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/brand","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/brand'),
(1029,7,'Documented model history','{"summary":"Triumph''s corporate history places the Street Triple launch in 2007 and the higher-specification Street Triple R in 2009.","source_name":"Triumph manufacturer archive","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/brand","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/brand'),
(524,1,'Model introduction','{"summary":"The KTM 390 Duke is a lightweight naked roadster within KTM''s Duke family.","source_name":"KTM manufacturer archive","source_url":"https://press.ktm.com/news-ktm-duke-30-years-of-pure-naked-motorcycling?id=192629&imageid=747186&l=international&menueid=3050","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://press.ktm.com/news-ktm-duke-30-years-of-pure-naked-motorcycling?id=192629&imageid=747186&l=international&menueid=3050'),
(524,7,'Documented model history','{"summary":"KTM''s 30-year Duke retrospective identifies the 390 Duke''s introduction in 2013, following the 200 Duke''s 2012 arrival.","source_name":"KTM manufacturer archive","source_url":"https://press.ktm.com/news-ktm-duke-30-years-of-pure-naked-motorcycling?id=192629&imageid=747186&l=international&menueid=3050","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://press.ktm.com/news-ktm-duke-30-years-of-pure-naked-motorcycling?id=192629&imageid=747186&l=international&menueid=3050'),
(205,1,'Model introduction','{"summary":"The 1290 Super Duke R is KTM''s large-capacity V-twin naked performance motorcycle.","source_name":"KTM manufacturer archive","source_url":"https://press.ktm.com/news-ktm-duke-30-years-of-pure-naked-motorcycling?id=192629&imageid=747186&l=international&menueid=3050","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://press.ktm.com/news-ktm-duke-30-years-of-pure-naked-motorcycling?id=192629&imageid=747186&l=international&menueid=3050'),
(205,7,'Documented model history','{"summary":"KTM identifies its launch in 2014, its first major revision in 2017, and a further redesigned generation in 2020. Specifications depend on model year.","source_name":"KTM manufacturer archive","source_url":"https://press.ktm.com/news-ktm-duke-30-years-of-pure-naked-motorcycling?id=192629&imageid=747186&l=international&menueid=3050","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://press.ktm.com/news-ktm-duke-30-years-of-pure-naked-motorcycling?id=192629&imageid=747186&l=international&menueid=3050'),
(523,1,'Model introduction','{"summary":"The 390 Adventure brings KTM''s small-capacity platform into a more travel-oriented adventure motorcycle format.","source_name":"KTM manufacturer archive","source_url":"https://press.ktm.com/news-ktm-reveal-triple-model-threat-at-eicma-2019?id=95910&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://press.ktm.com/news-ktm-reveal-triple-model-threat-at-eicma-2019?id=95910&l=uk&menueid=5904'),
(523,7,'Documented model history','{"summary":"KTM''s UK EICMA announcement on 5 November 2019 included the 390 Adventure among its new motorcycles for 2020.","source_name":"KTM manufacturer archive","source_url":"https://press.ktm.com/news-ktm-reveal-triple-model-threat-at-eicma-2019?id=95910&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://press.ktm.com/news-ktm-reveal-triple-model-threat-at-eicma-2019?id=95910&l=uk&menueid=5904'),
(529,1,'Model introduction','{"summary":"The KTM 890 Duke R is a performance-focused middleweight naked motorcycle in the Duke family.","source_name":"KTM manufacturer archive","source_url":"https://press.ktm.com/news-ktm-reveal-triple-model-threat-at-eicma-2019?id=95910&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://press.ktm.com/news-ktm-reveal-triple-model-threat-at-eicma-2019?id=95910&l=uk&menueid=5904'),
(529,7,'Documented model history','{"summary":"KTM''s 2019 EICMA release unveiled the 890 Duke R for the 2020 range, alongside other distinct KTM model launches.","source_name":"KTM manufacturer archive","source_url":"https://press.ktm.com/news-ktm-reveal-triple-model-threat-at-eicma-2019?id=95910&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://press.ktm.com/news-ktm-reveal-triple-model-threat-at-eicma-2019?id=95910&l=uk&menueid=5904'),
(527,1,'Model introduction','{"summary":"The 790 Duke expanded KTM''s naked road range towards a parallel-twin middleweight platform.","source_name":"KTM manufacturer archive","source_url":"https://press.ktm.com/news-ktm-streets-ahead?id=41867&imageid=95623&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://press.ktm.com/news-ktm-streets-ahead?id=41867&imageid=95623&l=uk&menueid=5904'),
(527,7,'Documented model history','{"summary":"KTM presented a 790 Duke prototype at EICMA in November 2016. The prototype announcement alone does not establish the production model''s exact launch date.","source_name":"KTM manufacturer archive","source_url":"https://press.ktm.com/news-ktm-streets-ahead?id=41867&imageid=95623&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Private documentary intake only; fact-specific year, country, version, rights and technical specs require separate verification."}'::jsonb,'https://press.ktm.com/news-ktm-streets-ahead?id=41867&imageid=95623&l=uk&menueid=5904')) v(model_id,section_number,title,content,url);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>22 THEN RAISE EXCEPTION 'Expected 22 private draft sections, inserted %',inserted; END IF;
 SELECT count(*) INTO public_after FROM public.motorcycle_universal_published_sections_v1;
 IF public_before<>public_after THEN RAISE EXCEPTION 'Public universal projection changed'; END IF;
END $$;